-- ExamGrind verified daily current-affairs desk: 12 November 2026.
-- Coverage window: substantive official releases on 11 November and recoverable late material.

insert into public.current_affairs_briefs (
  slug, published_on, title, summary, why_it_matters, background,
  source_title, source_url, source_publisher, source_published_on,
  prelims_takeaways, quick_check, visual_data, status, reviewed_at
) values
(
$$2026-11-12-stand-up-india-continuation$$, $$2026-11-12$$,
$$Stand-Up India continues until March 2031$$,
$$The Union Cabinet continued the Stand-Up India Scheme for five years until 31 March 2031. The decision targets an additional 2.5 lakh women, Scheduled Caste and Scheduled Tribe entrepreneurs and approves a Rs 4,111 crore credit-guarantee corpus.$$,
$$This is a core financial-inclusion and entrepreneurship update. It tests the eligible groups, the greenfield-enterprise condition and the distinction between a loan scheme and a direct cash grant.$$,
$$Launched in April 2016, Stand-Up India supports women and SC/ST entrepreneurs setting up new enterprises in manufacturing, services, trading and allied agricultural activities. The official release specifies composite or term loans above Rs 10 lakh and up to Rs 1 crore, with credit-guarantee coverage of 85% of the loan amount.$$,
$$Cabinet approves Continuation of Stand-Up India Scheme$$,
$$https://www.pib.gov.in/PressReleseDetailm.aspx?PRID=2334978&lang=1&reg=3$$,
$$Ministry of Finance / Press Information Bureau$$, $$2026-11-11$$,
$$["Stand-Up India has been continued up to 31 March 2031.","It promotes greenfield entrepreneurship among women and SC/ST entrepreneurs.","The stated loan range is above Rs 10 lakh and up to Rs 1 crore.","The Cabinet approved a Rs 4,111 crore credit-guarantee corpus."]$$::jsonb,
$$[{"question":"Is Stand-Up India described as a direct grant for any existing small business?","answer":"No. It provides loan-based support for eligible women and SC/ST entrepreneurs establishing new or greenfield enterprises."}]$$::jsonb,
$${"title":"Stand-Up India support chain","steps":["An eligible woman or SC/ST entrepreneur proposes a greenfield enterprise.","A lending institution considers a composite or term loan.","Credit guarantee reduces lender default risk.","The scheme aims to widen formal entrepreneurship among underserved groups."]}$$::jsonb, $$published$$, now()
),
(
$$2026-11-12-cgfmu-continuation$$, $$2026-11-12$$,
$$Credit Guarantee Fund for Micro Units continues through 2030-31$$,
$$The Union Cabinet continued the Credit Guarantee Fund for Micro Units for five years up to 31 March 2031, with a Rs 5,000 crore corpus. The fund gives lending institutions credit-guarantee coverage for specified loans under Pradhan Mantri Mudra Yojana.$$,
$$The decision links MUDRA lending, collateral-free micro credit and the National Credit Guarantee Trustee Company. It is useful for distinguishing a guarantee to lenders from a subsidy paid directly to a borrower.$$,
$$CGFMU was launched in January 2016 and is administered through National Credit Guarantee Trustee Company Limited. The release says it covers eligible PMMY loans up to Rs 20 lakh, specified PMJDY overdrafts and some SHG loans; it reduces the standard annual guarantee fee from 1% to 0.75%. $$,
$$Cabinet approves continuation of Credit Guarantee Fund for Micro Units$$,
$$https://www.pib.gov.in/PressReleseDetailm.aspx?PRID=2334977&lang=1&reg=3$$,
$$Ministry of Finance / Press Information Bureau$$, $$2026-11-11$$,
$$["CGFMU has been continued until 31 March 2031.","It provides guarantees to lending institutions, not a cash guarantee paid to borrowers.","The fund is linked to loans under Pradhan Mantri Mudra Yojana.","NCGTC administers the guarantee mechanism cited in the release."]$$::jsonb,
$$[{"question":"Who receives CGFMU's credit guarantee coverage?","answer":"Eligible lending institutions receive it against default risk on specified micro-credit facilities."}]$$::jsonb,
$${"title":"How CGFMU supports micro credit","steps":["A lender extends an eligible micro-enterprise loan.","CGFMU provides prescribed guarantee coverage through NCGTC.","The guarantee moderates the lender's default-risk exposure.","Formal credit can reach eligible micro borrowers without collateral dependence."]}$$::jsonb, $$published$$, now()
),
(
$$2026-11-12-rabi-nbs-pk-fertiliser-rates$$, $$2026-11-12$$,
$$Cabinet approves Rabi nutrient-based subsidy rates for P&K fertilisers$$,
$$The Union Cabinet approved Nutrient Based Subsidy rates for phosphatic and potassic fertilisers for Rabi 2026-27, applicable from 1 October 2026 to 31 March 2027. The stated tentative budget requirement is Rs 62,370.02 crore.$$,
$$NBS is a recurring but highly examinable agriculture-policy mechanism. This update reinforces the difference between nutrient-based support for P&K fertilisers and the separate policy treatment commonly associated with urea.$$,
$$The NBS Scheme has governed subsidy on P&K fertilisers since 1 April 2010. The release says 28 P&K fertiliser grades, including DAP and NPKS grades, are supplied through manufacturers and importers at subsidised prices; approved rates are paid to companies so fertilisers remain affordable to farmers.$$,
$$Cabinet approves Nutrient Based Subsidy rates for Rabi 2026-27 on Phosphatic and Potassic fertilisers$$,
$$https://www.pib.gov.in/PressReleseDetailm.aspx?PRID=2334974&lang=1&reg=3$$,
$$Ministry of Chemicals and Fertilizers / Press Information Bureau$$, $$2026-11-11$$,
$$["The approved NBS period is 1 October 2026 to 31 March 2027.","NBS applies to phosphatic and potassic fertilisers, including DAP and NPKS grades.","The scheme has operated since 1 April 2010.","The stated Rabi 2026-27 tentative requirement is Rs 62,370.02 crore."]$$::jsonb,
$$[{"question":"Under the NBS framework, who receives the subsidy payment described in the release?","answer":"It is provided to fertiliser companies at approved and notified rates so products can be sold to farmers at affordable prices."}]$$::jsonb,
$${"title":"NBS from nutrient rates to farm supply","steps":["Government sets Rabi nutrient-based subsidy rates.","Manufacturers and importers supply eligible P&K fertiliser grades.","Subsidy support offsets part of the supply cost.","Farmers access fertilisers at subsidised prices."]}$$::jsonb, $$published$$, now()
),
(
$$2026-11-12-aqua-line-noida-extension$$, $$2026-11-12$$,
$$Aqua Line extension between Noida and Greater Noida is approved$$,
$$The Union Cabinet approved an 8.449-kilometre extension of the Aqua Line from Noida Sector-51 to Greater Noida Sector-04, with five elevated stations. The release says the operational network for Noida and Greater Noida will then total 71.878 kilometres.$$,
$$The project is a useful urban-transport and infrastructure item. It tests metro-network integration, especially the planned interchange at Noida Sector-61 on the Blue Line.$$,
$$The Aqua Line is part of the Noida Metro Rail Project. The approved extension is intended to improve connectivity between Noida and Greater Noida and provide a direct interchange with the Delhi Metro Blue Line at Noida Sector-61; approval is not the same as completion or commencement of passenger service.$$,
$$Cabinet Approves extension of Aqua Line Metro Rail Corridor from Noida Sector-51 to Greater Noida Sector-04$$,
$$https://www.pib.gov.in/PressReleseDetailm.aspx?PRID=2334971&lang=1&reg=3$$,
$$Ministry of Housing and Urban Affairs / Press Information Bureau$$, $$2026-11-11$$,
$$["The approved Aqua Line extension is 8.449 km long.","It will have five elevated stations.","It runs from Noida Sector-51 to Greater Noida Sector-04.","The planned interchange is at Noida Sector-61 on the Blue Line."]$$::jsonb,
$$[{"question":"Does Cabinet approval mean the Aqua Line extension has already begun operations?","answer":"No. The release approves the project; operationalisation is a later stage."}]$$::jsonb,
$${"title":"Aqua Line connectivity plan","steps":["The Union Cabinet approves the extension.","Five elevated stations are planned across the new corridor.","Noida Sector-61 is designed as the Blue Line interchange.","The corridor aims to integrate Noida and Greater Noida public transport."]}$$::jsonb, $$published$$, now()
),
(
$$2026-11-12-yuge-yugeen-bharat-museum$$, $$2026-11-12$$,
$$CCEA approves the Yuge Yugeen Bharat Museum project$$,
$$The Cabinet Committee on Economic Affairs approved development of the Yuge Yugeen Bharat Museum at the North and South Block complex in New Delhi, at an estimated cost of Rs 3,230 crore. The project is to adaptively reuse the historic complex as a public cultural institution.$$,
$$This is a cultural-infrastructure decision that links heritage conservation, adaptive reuse and museum administration. It also provides a clear example of the CCEA's role in approving a major public-investment project.$$,
$$The museum is envisaged as a civilisational museum presenting tangible and intangible heritage through an integrated narrative. The release gives a proposed built-up area of about 1,78,509 square metres and says the project will use contemporary museum practices, immersive technologies and visitor-centred interpretation.$$,
$$Cabinet approves Development of Yuge Yugeen Bharat Museum at North and South Block Complex, New Delhi$$,
$$https://www.pib.gov.in/PressReleseDetailm.aspx?PRID=2334964&lang=1&reg=3$$,
$$Ministry of Culture / Press Information Bureau$$, $$2026-11-11$$,
$$["The approving body is the Cabinet Committee on Economic Affairs.","The project site is the North and South Block complex in New Delhi.","The estimated project cost is Rs 3,230 crore.","Adaptive reuse will retain the complex's architectural and heritage character."]$$::jsonb,
$$[{"question":"What conservation approach does the museum decision specify for North and South Block?","answer":"Adaptive reuse: retaining the historic character while converting the complex into a public cultural institution."}]$$::jsonb,
$${"title":"From historic complex to museum","steps":["CCEA approves the public-investment project.","North and South Block are adapted rather than replaced.","Museum design brings heritage narratives and contemporary interpretation together.","The completed institution is intended to serve the public as a cultural museum."]}$$::jsonb, $$published$$, now()
),
(
$$2026-11-12-dgft-battery-black-mass-export-prohibition$$, $$2026-11-12$$,
$$DGFT prohibits exports of lithium-ion battery black mass$$,
$$The Directorate General of Foreign Trade changed the export policy for lithium-ion battery black mass under ITC(HS) 85491400 from Free to Prohibited, with immediate effect. The official notice identifies Notification No. 49/2026-27 dated 10 November 2026.$$,
$$The measure connects foreign-trade policy with critical-mineral security, battery recycling and the circular economy. It is important not to confuse an export prohibition with a ban on battery recycling or battery use.$$,
$$Black mass is the powdery material produced when end-of-life lithium-ion batteries and manufacturing waste are shredded. It contains recoverable lithium, cobalt, nickel and manganese; the government says retaining it domestically should support recycling and refining capacity and reduce import dependence.$$,
$$DGFT prohibits export of Lithium-Ion Battery Black Mass to strengthen domestic recycling and critical mineral recovery$$,
$$https://www.pib.gov.in/PressReleseDetailm.aspx?PRID=2335019&lang=1&reg=3$$,
$$Directorate General of Foreign Trade, Department of Commerce / Press Information Bureau$$, $$2026-11-11$$,
$$["ITC(HS) 85491400 covers the specified lithium-ion battery black mass item.","Its export policy changed from Free to Prohibited.","Black mass can contain lithium, cobalt, nickel and manganese.","The measure aims to secure domestic feedstock for recycling and refining."]$$::jsonb,
$$[{"question":"What activity did the DGFT notification prohibit?","answer":"The export of the specified lithium-ion battery black mass; it did not prohibit domestic recycling."}]$$::jsonb,
$${"title":"Battery waste to critical-mineral recovery","steps":["End-of-life batteries and manufacturing waste are processed.","Shredding yields black mass containing recoverable materials.","The export restriction retains that material in India.","Domestic recyclers and refiners can recover critical minerals for new supply chains."]}$$::jsonb, $$published$$, now()
),
(
$$2026-11-12-bimstec-health-ministers-statement$$, $$2026-11-12$$,
$$First BIMSTEC Health Ministers' Meeting adopts a joint statement$$,
$$The first BIMSTEC Health Ministers' Meeting in Colombo unanimously adopted a Joint Ministerial Statement. India described the outcome as strengthening regional health cooperation among the Bay of Bengal grouping's member states.$$,
$$The development is relevant to regional organisations and public-health diplomacy. It should be remembered as a ministerial statement, not as a new treaty or a supranational health regulator.$$,
$$BIMSTEC brings together Bangladesh, Bhutan, India, Myanmar, Nepal, Sri Lanka and Thailand. Its regional focus links the Bay of Bengal with South and South-East Asia; the health meeting adds sectoral cooperation to this wider institutional framework.$$,
$$India Strengthens Regional Health Partnerships as First BIMSTEC Health Ministers’ Meeting Unanimously Adopts Joint Ministerial Statement in Colombo$$,
$$https://www.pib.gov.in/PressReleseDetailm.aspx?PRID=2335080&lang=1&reg=3$$,
$$Ministry of Health and Family Welfare / Press Information Bureau$$, $$2026-11-11$$,
$$["The meeting was the first BIMSTEC Health Ministers' Meeting.","It was held in Colombo.","The stated outcome was unanimous adoption of a Joint Ministerial Statement.","BIMSTEC has seven members: Bangladesh, Bhutan, India, Myanmar, Nepal, Sri Lanka and Thailand."]$$::jsonb,
$$[{"question":"Which country is not a BIMSTEC member: Thailand or Pakistan?","answer":"Pakistan is not a BIMSTEC member; Thailand is one of the seven members."}]$$::jsonb,
$${"title":"BIMSTEC health cooperation","steps":["BIMSTEC convenes ministers from seven Bay of Bengal-region states.","Health ministers meet in Colombo.","Members adopt a Joint Ministerial Statement.","The statement creates a shared political basis for regional health cooperation, rather than a new treaty body."]}$$::jsonb, $$published$$, now()
),
(
$$2026-11-12-indian-visa-regime-rationalisation$$, $$2026-11-12$$,
$$India rationalises visa categories and application forms$$,
$$The Ministry of Home Affairs reported that the main categories in India's visa framework were reduced from 13 to nine and sub-categories from 49 to 23. It also said application-form fields across the 23 sub-categories were cut by 65% to 70%, with system updates under way for implementation.$$,
$$This is an important governance and international-mobility update. It tests the classification of visa categories while avoiding the mistaken conclusion that visa requirements or security checks have been abolished.$$,
$$The rationalised framework includes Business, Diplomatic, Work, Journalist, Medical, Official, Student, Visitor and Miscellaneous visas. The erstwhile Tourist Visa is renamed Visitor Visa; e-visas remain processed through electronic travel authorisation, and the release says the facility is available to nationals of 172 countries.$$,
$$Government of India rationalizes Indian visa regime$$,
$$https://www.pib.gov.in/PressReleseDetailm.aspx?PRID=2335182&lang=1&reg=3$$,
$$Ministry of Home Affairs / Press Information Bureau$$, $$2026-11-11$$,
$$["The main visa categories were reduced from 13 to nine.","Sub-categories were reduced from 49 to 23.","The Tourist Visa category is renamed Visitor Visa.","The release says forms were simplified by reducing fields by 65% to 70%."]$$::jsonb,
$$[{"question":"Did the rationalisation eliminate eligibility conditions for entry into India?","answer":"No. It simplifies and consolidates categories and forms while visas remain subject to applicable eligibility conditions and processing."}]$$::jsonb,
$${"title":"Visa-framework rationalisation","steps":["Similar travel purposes are grouped into clearer visa categories.","Main and sub-categories are consolidated.","Application forms request fewer fields.","IT systems implement the revised purpose-based framework."]}$$::jsonb, $$published$$, now()
),
(
$$2026-11-12-rbi-domestic-money-transfer-directions$$, $$2026-11-12$$,
$$RBI consolidates domestic money-transfer rules$$,
$$The Reserve Bank of India issued the Domestic Money Transfer Directions, 2026 with immediate effect, consolidating earlier instructions for cash pay-out and cash pay-in transfer services. The Directions apply, as relevant, to scheduled commercial banks, RRBs, cooperative banks and authorised payment-system operators and participants.$$,
$$This is a direct payments-regulation update. It is useful for understanding formal remittance channels, transaction caps, customer safeguards and the RBI's authority under the Payment and Settlement Systems Act, 2007.$$,
$$For cash pay-out, the Directions permit up to Rs 10,000 per transaction and a Rs 25,000 monthly limit per beneficiary. A walk-in customer can remit up to Rs 50,000 to a beneficiary account through NEFT; additional-factor authentication, remitter records and monitoring safeguards apply to specified services.$$,
$$Reserve Bank of India (Domestic Money Transfer) Directions, 2026$$,
$$https://www.rbi.org.in/Scripts/NotificationUser.aspx?Id=13752&Mode=0$$,
$$Reserve Bank of India$$, $$2026-11-11$$,
$$["The Directions are issued under the Payment and Settlement Systems Act, 2007.","They take effect immediately.","Cash pay-out is capped at Rs 10,000 per transaction and Rs 25,000 per beneficiary per month.","Card-to-card transfers are excluded from these Directions."]$$::jsonb,
$$[{"question":"What is the cash pay-out ceiling under the RBI Directions?","answer":"Rs 10,000 per transaction, subject to an overall Rs 25,000 monthly ceiling per beneficiary."}]$$::jsonb,
$${"title":"Domestic money-transfer safeguards","steps":["A regulated bank or payment participant provides the permitted transfer service.","Transaction and monthly caps limit cash-based remittance exposure.","Identity, authentication and monitoring safeguards apply.","Settlement uses RBI-approved payment systems and grievances can enter the Ombudsman framework."]}$$::jsonb, $$published$$, now()
),
(
$$2026-11-12-sebi-fatca-crs-reporting-revision$$, $$2026-11-12$$,
$$SEBI revises FATCA and CRS reporting requirements$$,
$$SEBI issued a circular revising reporting requirements under the Foreign Account Tax Compliance Act and Common Reporting Standard framework to reflect the Income-tax Act, 2025 and Income-tax Rules, 2026. The circular is numbered HO/38/14/(18)2026-MIRSD-POD2/I/25560/2026.$$,
$$This is a high-value financial-regulation update linking securities-market intermediaries with cross-border tax-information reporting. It is a revision of reporting requirements, not a claim that SEBI itself administers foreign income-tax systems.$$,
$$FATCA is a United States tax-information reporting framework, while the CRS is an OECD-developed system for automatic exchange of financial-account information between participating jurisdictions. SEBI regulates the securities market and may prescribe compliance requirements for its regulated entities.$$,
$$Reporting requirement under FATCA and CRS revised through Income-tax Act, 2025 read with Income-tax Rules, 2026$$,
$$https://www.sebi.gov.in/legal/circulars/nov-2026/reporting-requirement-under-foreign-account-tax-compliance-act-fatca-and-common-reporting-standard-crs-revised-through-income-tax-act-2025-read-with-income-tax-rules-2026_105705.html$$,
$$Securities and Exchange Board of India$$, $$2026-11-11$$,
$$["SEBI issued the revision on 11 November 2026.","The circular aligns FATCA and CRS reporting requirements with the Income-tax Act, 2025 and Income-tax Rules, 2026.","FATCA is associated with United States tax-information reporting.","CRS supports automatic exchange of financial-account information among participating jurisdictions."]$$::jsonb,
$$[{"question":"Are FATCA and CRS identical systems?","answer":"No. FATCA is a United States framework, whereas CRS is an OECD-developed multilateral standard for automatic exchange of financial-account information."}]$$::jsonb,
$${"title":"Cross-border financial-account reporting","steps":["A financial intermediary identifies reportable account information under applicable rules.","FATCA and CRS prescribe international tax-information reporting frameworks.","SEBI updates the compliance requirement for its regulated market ecosystem.","Reporting supports exchange of relevant information through the authorised tax-administration framework."]}$$::jsonb, $$published$$, now()
)
on conflict (slug) do update set
  title = excluded.title, summary = excluded.summary, why_it_matters = excluded.why_it_matters,
  background = excluded.background, source_title = excluded.source_title, source_url = excluded.source_url,
  source_publisher = excluded.source_publisher, source_published_on = excluded.source_published_on,
  prelims_takeaways = excluded.prelims_takeaways, quick_check = excluded.quick_check,
  visual_data = excluded.visual_data, status = excluded.status, reviewed_at = now(),
  updated_at = now();

insert into public.current_affairs_exam_tags (brief_id, exam_id)
select briefs.id, exams.id from public.current_affairs_briefs briefs cross join public.exams exams
where briefs.slug in (
$$2026-11-12-stand-up-india-continuation$$,
$$2026-11-12-cgfmu-continuation$$,
$$2026-11-12-rabi-nbs-pk-fertiliser-rates$$,
$$2026-11-12-aqua-line-noida-extension$$,
$$2026-11-12-yuge-yugeen-bharat-museum$$,
$$2026-11-12-dgft-battery-black-mass-export-prohibition$$,
$$2026-11-12-bimstec-health-ministers-statement$$,
$$2026-11-12-indian-visa-regime-rationalisation$$,
$$2026-11-12-rbi-domestic-money-transfer-directions$$,
$$2026-11-12-sebi-fatca-crs-reporting-revision$$
)
and exams.slug in ($$cuet$$, $$ssc-cgl$$, $$uppsc-ro-aro$$, $$up-secretariat-ro-aro$$)
on conflict (brief_id, exam_id) do nothing;
